import { additionalBrainRankQuestions } from "../src/content/quizzes/brainrank-expanded";
import { behavioralSeedSql } from "./behavioral-seed";

const sqlText = (value: string) => `'${value.replace(/'/g, "''")}'`;
const json = (value: unknown) => `${sqlText(JSON.stringify(value))}::jsonb`;

/** Only inserts new content. Safe for historical attempts, results and repeat execution. */
export function questionBankExpansionSql(): string {
  const lines = [
    "-- Generated by scripts/question-bank-expansion.ts; do not edit content in SQL.",
    "do $$ declare v_version uuid; v_question uuid; v_option uuid; begin",
    "select v.id into strict v_version from meqyro.quiz_versions v join meqyro.quizzes q on q.id = v.quiz_id where q.slug = 'brainrank' and v.version = '1.2';",
  ];
  for (const q of additionalBrainRankQuestions) {
    lines.push(`insert into meqyro.questions (quiz_version_id, stable_key, position, kind, scoring_key, metadata)
      values (v_version, '${q.stableKey}', ${q.position}, 'SINGLE_CHOICE', ${json({ dimension: q.dimension, difficulty: q.difficulty })}, ${json(q.clue ? { clue: q.clue } : {})})
      on conflict (quiz_version_id, stable_key) do nothing;
      select id into strict v_question from meqyro.questions where quiz_version_id = v_version and stable_key = '${q.stableKey}';`);
    for (const [locale, prompt] of Object.entries(q.prompt)) {
      lines.push(
        `insert into meqyro.question_translations (question_id, locale, prompt) values (v_question, '${locale}', ${sqlText(prompt)}) on conflict (question_id, locale) do nothing;`,
      );
    }
    for (const option of q.options) {
      lines.push(`insert into meqyro.options (question_id, stable_key, position, scoring_value)
        values (v_question, '${option.stableKey}', ${option.position}, ${json({ isCorrect: option.isCorrect })}) on conflict (question_id, stable_key) do nothing;
        select id into strict v_option from meqyro.options where question_id = v_question and stable_key = '${option.stableKey}';`);
      for (const [locale, label] of Object.entries(option.label)) {
        lines.push(
          `insert into meqyro.option_translations (option_id, locale, label) values (v_option, '${locale}', ${sqlText(label)}) on conflict (option_id, locale) do nothing;`,
        );
      }
    }
  }
  lines.push("end $$;");
  return lines.join("\n") + "\n" + behavioralSeedSql(true);
}
